function storyRewardOptions(count){
  const pool=[
    ['Sharpened Edge','Run · +12% strike damage','damage'],
    ['Vitality Seal','Run · +18 maximum health','health'],
    ['Chakra Reservoir','Run · restore 40 chakra','chakra'],
    ['Swift Current','Run · +12 movement speed','speed'],
    ['Iron Guard','Run · +25 guard stamina','guard'],
    ['Ember Step','Run · dash cooldown -15%','dash'],
    ['Sealing Focus','Run · skill cooldown -12%','focus'],
    ['Hunter’s Instinct','Run · parry window +0.10s','parry'],
    ['Second Wind','Run · heal 30 health','heal']
  ];
  const out=[]; const used=new Set();
  while(out.length<count){const o=pool[Math.floor(Math.random()*pool.length)];if(!used.has(o[2])){used.add(o[2]);out.push(o)}}
  return out;
}

