function showRewards(){
  const count=storyRewardCount||4;
  const options=storyRewardOptions(count);
  modalOpen=true;
  modal.classList.add('open');
  modal.innerHTML=`<div class="modal-card reward-modal"><p class="eyebrow">ROOM ${roomIndex+1} CLEARED · ${roomIndex===4?'BOSS':roomIndex===3?'MINI-BOSS':roomIndex===2?'ELITE':'STANDARD'}</p><h2>CHOOSE ONE REWARD</h2><p>Exactly one card may be selected. The remaining choices will disappear.</p><div class="reward-grid reward-grid-${options.length}" style="grid-template-columns:repeat(${options.length},minmax(90px,1fr))">${options.map(r=>`<button class="reward-card" data-card="${r.code}"><span class="rarity rarity-${r.rarity.toLowerCase()}">${r.rarity}</span><strong>${r.art} ${r.name}</strong><small>${r.category} · Temporary</small><small>${r.effect}</small><small>${r.description}</small></button>`).join('')}</div><div class="modal-actions"><button data-action="continue" disabled>CONTINUE</button></div><div id="special-reward"></div></div>`;
  modal.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>{
    if(runSelectedReward)return;
    runSelectedReward=true;
    const card=RUN_CARD_DB.find(r=>r.code===b.dataset.card);
    if(!card)return;
    applyRunReward(card.code);
    modal.querySelectorAll('[data-card]').forEach(x=>{x.disabled=true;x.classList.remove('selected');});
    b.classList.add('selected');
    b.innerHTML=`<span class="rarity rarity-${card.rarity.toLowerCase()}">${card.rarity}</span><strong>✓ ${card.name}</strong><small>SELECTED · ${card.effect}</small><small>${card.description}</small>`;
    modal.querySelector('[data-action=continue]').disabled=false;
  });
  // Independent 0.5% Rinnegan reveal: it never consumes or replaces ordinary choices.
  if(!saved.rinnegan&&Math.random()<0.005){
    saved.rinnegan=true;
    saveProgress();
    modal.querySelector('#special-reward').innerHTML='<p class="rinnegan-reveal">✦ MYTHIC REVEAL · RINNEGAN UNLOCKED ✦</p>';
  }
  modal.querySelector('[data-action=continue]').onclick=()=>{if(!runSelectedReward)return;finishRoomChoice();};
}

