/* Title screen: hard-edged pixel-art panel system, paired with the canvas scene. */
.screen{background:#0b122044;transition:opacity .2s steps(4)}
.menu-card{width:min(510px,64vw);max-width:510px;padding:24px 24px 20px;background:#101a28f2;border:4px solid #d6ad70;box-shadow:0 0 0 4px #26384a,0 0 0 8px #111a27,10px 10px 0 #090f18;image-rendering:pixelated}
.menu-card:before,.menu-card:after{content:"";position:absolute;width:12px;height:12px;background:#e6c286;z-index:2;pointer-events:none}
.menu-card:before{left:-4px;top:-4px}.menu-card:after{right:-4px;bottom:-4px}
.eyebrow,.menu-foot,.eyebrow{font-family:'Press Start 2P',monospace;font-size:8px;line-height:2;color:#dfb46f;letter-spacing:0;margin:0 0 12px}
.menu-card h1{font-family:'Press Start 2P',monospace;font-size:clamp(24px,3.8vw,38px);line-height:1.55;letter-spacing:0;margin:0 0 10px;font-weight:400;color:#f6eee0;text-shadow:3px 3px 0 #273a4c,5px 5px 0 #090f18}
.menu-card h1 span{font-size:.34em;letter-spacing:0;color:#e3b46e;vertical-align:middle;white-space:nowrap}
.subtitle{font-family:'Press Start 2P',monospace;font-size:7px;line-height:2.2;color:#bbc6cb;margin:0 0 15px;max-width:460px}
.menu-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.menu-actions button{height:39px;padding:0 10px;border:0;outline:2px solid #080f18;outline-offset:-4px;box-shadow:inset 0 0 0 2px #526273,4px 4px 0 #080f18;border-radius:0;font-family:'Press Start 2P',monospace;font-size:7px;line-height:1.5;letter-spacing:0;color:#f2e8d5;cursor:pointer;transition:transform .08s steps(2),filter .08s steps(2)}
.menu-actions button:hover{transform:translate(-1px,-1px);filter:brightness(1.2)}
.menu-actions button:active{transform:translate(2px,2px);box-shadow:inset 0 0 0 2px #526273,1px 1px 0 #080f18}
.menu-actions .primary{grid-column:1/-1;background:#a9443b;border-color:transparent!important;box-shadow:inset 0 0 0 2px #e58b60,4px 4px 0 #080f18}
.primary b{font-family:monospace;font-size:16px;margin-left:12px}
.menu-actions .secondary{background:#26384a}
.menu-foot{display:flex;gap:10px;justify-content:space-between;margin-top:16px;color:#85949e;font-size:6px;line-height:1.8;letter-spacing:0}
.menu-foot span{max-width:48%}
.menu-mark{display:none}
.modal{background:#080d16dd;backdrop-filter:none}
.modal-card{padding:24px;background:#101a28;border:4px solid #d6ad70;border-radius:0;box-shadow:0 0 0 4px #26384a,8px 8px 0 #060a11}
.modal-card h2{font-family:'Press Start 2P',monospace;font-size:clamp(17px,2.4vw,25px);line-height:1.7;letter-spacing:0;color:#f1e7d5;text-shadow:2px 2px #090f18}
.modal-card p{font-family:'Press Start 2P',monospace;font-size:8px;line-height:2;color:#b9c3c6}
.modal-actions button{border:0;border-radius:0;background:#26384a;box-shadow:inset 0 0 0 2px #526273,4px 4px 0 #080f18;font:7px/1.7 'Press Start 2P',monospace;letter-spacing:0;padding:12px 14px}
.modal-actions button:hover{background:#8c483c}
@media (max-width:700px){.screen{padding:5%}.menu-card{width:min(510px,92vw);max-width:none;padding:17px 17px 15px}.menu-card h1{font-size:clamp(19px,5vw,32px);line-height:1.5}.subtitle{font-size:6px;line-height:2}.menu-actions{gap:7px}.menu-actions button{height:35px;font-size:6px;padding:0 5px}.menu-foot{display:none}.eyebrow{font-size:7px}.modal-card{padding:17px}.modal-card p{font-size:7px}}
@media (max-height:430px){.menu-card{padding:12px 17px}.menu-card h1{font-size:clamp(18px,4.2vw,29px);line-height:1.35;margin-bottom:5px}.eyebrow{margin-bottom:5px}.subtitle{margin-bottom:7px;font-size:6px}.menu-actions button{height:31px}.menu-foot{display:none}}

