+.menu-card h1{font-family:'Press Start 2P',monospace;font-size:clamp(24px,3.8vw,38px);line-height:1.55;letter-spacing:0;margin:0 0 10px;font-weight:400;color:#f6eee0;text-shadow:3px 3px 0 #273a4c,5px 5px 0 #090f18}
